<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/services/AdminWorkspaceService.php';
ini_set('display_errors','1');error_reporting(E_ALL);
function verify(bool $condition,string $message): void {if(!$condition)throw new RuntimeException($message);}
function denied(callable $fn,int $code=0): void {try{$fn();}catch(Throwable $e){verify(!$code||$e->getCode()===$code,'Unexpected rejection code');return;}throw new LogicException('Expected rejection');}
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);
$clock=gmdate('Y-m-d H:i:s');$db->sqliteCreateFunction('NOW',fn()=>$clock);$db->sqliteCreateFunction('UTC_TIMESTAMP',fn()=>$clock);
$db->exec("CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE,email TEXT UNIQUE,full_name TEXT,password_hash TEXT,role TEXT,status TEXT,is_online INTEGER DEFAULT 0,last_active_at TEXT,last_seen_at TEXT,remember_token TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,deleted_at TEXT);
CREATE TABLE user_profiles(user_id INTEGER PRIMARY KEY,academic_program_id INTEGER);
CREATE TABLE institutions(id INTEGER PRIMARY KEY,name TEXT);
CREATE TABLE academic_programs(id INTEGER PRIMARY KEY,code TEXT,name TEXT,institution_id INTEGER,is_active INTEGER);
CREATE TABLE interest_tags(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,slug TEXT UNIQUE,category TEXT);
CREATE TABLE servers(id INTEGER PRIMARY KEY,name TEXT,description TEXT,status TEXT,type TEXT,owner_id INTEGER);
CREATE TABLE channels(id INTEGER PRIMARY KEY,server_id INTEGER,name TEXT,type TEXT,is_private INTEGER,is_locked INTEGER);
CREATE TABLE server_members(server_id INTEGER,user_id INTEGER);
CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT,channel_id INTEGER,sender_id INTEGER,content TEXT,content_type TEXT,is_pinned INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,is_deleted INTEGER DEFAULT 0);
CREATE TABLE study_sessions(user_id INTEGER,started_at TEXT);
CREATE TABLE content_reports(id INTEGER PRIMARY KEY,server_id INTEGER,status TEXT);
CREATE TABLE facilitator_requests(id INTEGER PRIMARY KEY,status TEXT);
CREATE TABLE feedback(id INTEGER PRIMARY KEY,user_id INTEGER,title TEXT,description TEXT,type TEXT,status TEXT,resolved_by INTEGER,created_at TEXT,updated_at TEXT);
CREATE TABLE activity_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT,level TEXT,entity_type TEXT,entity_id INTEGER,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE peer_matches(id INTEGER PRIMARY KEY,status TEXT,match_score REAL);
CREATE TABLE ai_sessions(id INTEGER PRIMARY KEY);
CREATE TABLE realtime_outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,target_id INTEGER,message_id INTEGER);");
$insert=$db->prepare('INSERT INTO users(id,username,email,full_name,role,status,created_at) VALUES(?,?,?,?,?,?,?)');
foreach([[1,'admin','admin@example.com','Admin','admin','active'],[2,'student','student@example.com','Student','student','offline'],[3,'facilitator','fac@example.com','Facilitator','facilitator','offline'],[4,'root','root@example.com','Root','super_admin','active'],[5,'k6_fixture','k6_fixture@example.invalid','Synthetic','student','active']] as $row)$insert->execute([...$row,$clock]);
$db->exec("INSERT INTO institutions VALUES(1,'OLFU');INSERT INTO academic_programs VALUES(1,'BSCS','Computer Science',1,1);INSERT INTO user_profiles VALUES(2,1);INSERT INTO servers VALUES(10,'Study group','Description','active','private',2),(11,'Faculty','Description','active','public',3);INSERT INTO channels VALUES(20,10,'announcements','announcement',0,0),(21,10,'general','text',0,0);INSERT INTO server_members VALUES(10,2);INSERT INTO content_reports VALUES(1,10,'pending'),(2,11,'pending');INSERT INTO facilitator_requests VALUES(1,'pending');INSERT INTO peer_matches VALUES(1,'accepted',75);INSERT INTO ai_sessions VALUES(1);");
$db->prepare("INSERT INTO messages(channel_id,sender_id,content,created_at) VALUES(20,2,'Real',?),(20,5,'Synthetic',?)")->execute([$clock,$clock]);
$db->prepare("INSERT INTO feedback VALUES(1,2,'Bug','Details','bug','open',NULL,?,NULL)")->execute([$clock]);
$svc=new AdminWorkspaceService($db);$actor=['id'=>1,'role'=>'admin'];
$overview=$svc->overview();verify($overview['stats']['users']===4,'Exclude synthetic users');verify($overview['stats']['reports_pending']===1,'Only student-owned reports');verify($overview['stats']['messages_today']===1,'Exclude synthetic messages');verify(count($overview['activity'])===1&&(int)$overview['activity'][0]['messages']===1,'Day aggregation');
$users=$svc->users(['page'=>1,'limit'=>2]);verify($users['total']===4&&count($users['items'])===2,'Real pagination');verify($svc->users(['q'=>'student','role'=>'student'])['total']===1,'Search/role filter');verify($svc->users(['include_tests'=>'1'])['total']===5,'Explicit synthetic inclusion');verify($svc->users(['q'=>"' OR 1=1 --"])['total']===0,'Bound search');
denied(fn()=>AdminWorkspaceService::paging(['page'=>-1]));denied(fn()=>$svc->users(['role'=>'invalid']));
$space=$svc->spaces(['q'=>'Study']);verify($space['total']===1&&$space['items'][0]['visibility']==='private','Canonical schema visibility fallback');verify($svc->spaces(['kind'=>'channels'])['total']===2,'Channel view');verify(count($svc->catalog()['programs'])===1,'Real catalog');
denied(fn()=>$svc->mutate('role',['user_id'=>1,'role'=>'student','expected_role'=>'admin','expected_status'=>'active'],$actor),403);
denied(fn()=>$svc->mutate('ban',['user_id'=>4,'reason'=>'Protected','expected_role'=>'super_admin','expected_status'=>'active'],$actor),403);
denied(fn()=>$svc->mutate('role',['user_id'=>2,'role'=>'super_admin','expected_role'=>'student','expected_status'=>'offline'],$actor));
denied(fn()=>$svc->mutate('ban',['user_id'=>2,'reason'=>'Reason','expected_role'=>'student','expected_status'=>'active'],$actor),409);
$svc->mutate('role',['user_id'=>2,'role'=>'facilitator','expected_role'=>'student','expected_status'=>'offline'],$actor);
$svc->mutate('ban',['user_id'=>2,'reason'=>'Reviewed violation','expected_role'=>'facilitator','expected_status'=>'offline'],$actor);
$svc->mutate('unban',['user_id'=>2,'reason'=>'Review completed','expected_role'=>'facilitator','expected_status'=>'banned'],$actor);
verify($svc->users(['q'=>'student'])['items'][0]['status']==='offline','Unban stays offline');
$svc->mutate('feedback_status',['feedback_id'=>1,'status'=>'resolved','expected_status'=>'open'],$actor);verify($svc->feedback(['status'=>'resolved'])['total']===1,'Feedback transition');denied(fn()=>$svc->mutate('feedback_status',['feedback_id'=>1,'status'=>'closed','expected_status'=>'open'],$actor),409);
$created=$svc->mutate('create_user',['username'=>'new_student','email'=>'new@example.com','full_name'=>'New Student','password'=>'safe-test-password-123','role'=>'student'],$actor);
verify((int)$db->query('SELECT COUNT(*) FROM user_profiles WHERE user_id='.$created['id'])->fetchColumn()===1,'Created profile');
$before=(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn();denied(fn()=>$svc->mutate('create_user',['username'=>'new_student','email'=>'second@example.com','full_name'=>'Second','password'=>'safe-test-password-123'],$actor));verify((int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()===$before,'Duplicate create rollback');
$svc->mutate('create_tag',['name'=>'Data Systems','category'=>'Technology'],$actor);verify(count($svc->catalog()['tags'])===1,'Tag persistence');
$_ENV['CENTRIFUGO_ENABLED']='true';$svc->mutate('announcement',['server_id'=>10,'title'=>'Notice','message'=>'Real announcement'],$actor);
verify((int)$db->query('SELECT COUNT(*) FROM realtime_outbox')->fetchColumn()===1,'Announcement delivery intent');
verify((int)$db->query("SELECT COUNT(*) FROM messages WHERE content='[**Notice**] Real announcement'")->fetchColumn()===1,'Announcement saved');
$db->exec('DROP TABLE realtime_outbox');$before=(int)$db->query('SELECT COUNT(*) FROM messages')->fetchColumn();denied(fn()=>$svc->mutate('announcement',['server_id'=>10,'title'=>'Rollback','message'=>'Must not persist'],$actor));verify((int)$db->query('SELECT COUNT(*) FROM messages')->fetchColumn()===$before,'Outbox failure rolls back announcement');
verify($svc->audit(['q'=>'admin.user'])['total']>=4,'Audited mutations');verify($svc->ai()['accuracy']===null,'Do not invent accuracy');
$db->exec('DROP TABLE study_sessions');$overview=$svc->overview();verify($overview['stats']['study_sessions_today']===null&&in_array('study_sessions',$overview['unavailable'],true),'Missing sources are unavailable');
echo "Admin workspace query, pagination, role protection, conflicts, audit, atomic announcements and availability checks passed\n";
